/**
 * @summary List reviews for an activity
 */
export const getListReviewsUrl = (id: string, params?: ListReviewsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/activities/${id}/reviews?${stringifiedParams}`
    : `/api/activities/${id}/reviews`;
};

export const listReviews = async (
  id: string,
  params?: ListReviewsParams,
  options?: RequestInit,
): Promise<Review[]> => {
  return customFetch<Review[]>(getListReviewsUrl(id, params), {
    ...options,
    method: "GET",
  });
};

export const getListReviewsQueryKey = (
  id: string,
  params?: ListReviewsParams,
) => {
  return [
    `/api/activities/${id}/reviews`,
    ...(params ? [params] : []),
  ] as const;
};

